/* @lc app=leetcode id=4050 lang=kotlin */ class Solution { fun minDays(n: Int): Int = IntArray(n + 1) { if (it == 0) 0 else 1_000_000_000 }.also { dp -> generateSequence(1) { it + 1 }.takeWhile { it * (it + 1) / 2 <= n }.forEach { k -> (k * (k + 1) / 2..minOf(n, k * (k + 1))).forEach { i -> dp[i] = if (i == k * (k + 1) / 2) k else minOf(dp[i], dp[i - k * (k + 1) / 2] + k + 1) } } }[n] }